import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"VideoScore: Building Automatic Metrics to Simulate Fine-grained Human Feedback for Video Generation","description":"","frontmatter":{"title":"VideoScore: Building Automatic Metrics to Simulate Fine-grained Human Feedback for Video Generation","arxiv":"2406.15252","date":"2024-06-21","authors":"Xuan He, Dongfu Jiang, Ge Zhang, Max Ku, Achint Soni, Sherman Siu, Haonan Chen, Abhranil Chandra, Ziyan Jiang, et al.","categories":"cs.CV, cs.AI","topics":"后训练与强化学习, 视频评测指标, 奖励模型","outline":[2,2]},"headers":[],"relativePath":"papers/2406.15252.md","filePath":"papers/2406.15252.md","lastUpdated":null}'),e={name:"papers/2406.15252.md"};function l(r,s,i,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="videoscore-building-automatic-metrics-to-simulate-fine-grained-human-feedback-for-video-generation" tabindex="-1">VideoScore: Building Automatic Metrics to Simulate Fine-grained Human Feedback for Video Generation <a class="header-anchor" href="#videoscore-building-automatic-metrics-to-simulate-fine-grained-human-feedback-for-video-generation" aria-label="Permalink to &quot;VideoScore: Building Automatic Metrics to Simulate Fine-grained Human Feedback for Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2406.15252" target="_blank" rel="noreferrer">2406.15252</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-06-21</td></tr><tr><td><strong>作者</strong></td><td>Xuan He, Dongfu Jiang, Ge Zhang, Max Ku, Achint Soni, Sherman Siu, Haonan Chen, Abhranil Chandra, Ziyan Jiang, et al.（共 19 位，末位 Wenhu Chen）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>先造 37.6K 条人工五维打分的生成视频数据集 VideoFeedback，再把 Mantis-Idefics2-8B 换成回归头微调成一个多维打分器，用它当人类反馈的可查询代理。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/post-training-rl">后训练与强化学习</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>abs 页 HTML 链接指向 <strong>v3</strong>（v1 2024-06-21，v2 2024-06-24，v3 2024-10-14），本文正文取自 v3。单位为 University of Waterloo、清华大学、Stardust.AI、University of Toronto、AI2；作者共 19 位，frontmatter 取前 9 位 + et al.。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>2024 年上半年视频生成模型每个月都在换代，但判断「哪个更好」的手段没跟上。论文把已有指标的失效归成三类，每一类都点了名。</p><p>第一类是<strong>分布级指标</strong>：FVD、IS 只能在一批样本上算，无法给单条视频打分。这直接堵死了它们做 RLHF 奖励模型的可能——RLHF 需要对每个 rollout 单独评分。第二类是<strong>单维特征指标</strong>：CLIP、DINO、BRISQUE 各自只覆盖一个侧面，而且都是用「相邻帧特征余弦相似度」这类代理量拼出来的。论文对 VBench 的批评很尖锐：绝大多数模型的 subject/background consistency 都在 97% 以上，这是对当时 T2V 真实能力的&quot;massive overestimation&quot;。第三类是<strong>MLLM 直接打分</strong>：VIEScore、VideoPhy 那一路直接 prompt GPT-4o 或 Gemini-1.5 出分，看起来最省事，但论文实测它们与人类的相关性也很低。</p><p>问题的根在数据：没有大规模、多维度、人工标注的生成视频评分集，就没法训一个真正学人类偏好的打分器。所以这篇论文其实做了两件事——先补数据（VideoFeedback），再训模型（VideoScore）。它的定位不只是「又一个 benchmark」，而是明确指向 RLHF：作者希望它能替代人类评分员，在 PPO/DPO 循环里提供逐样本的稠密反馈。这一动机与同期的 <a href="/notes/papers/2405.18750">T2V-Turbo</a>、<a href="/notes/papers/2407.08737">VADER</a> 直接对接——后两者当时能用的视频侧奖励只有为检索训练的通用模型。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>VBench</strong> 是当时最完整的多维评测套件，但它的每一维都由一个现成的特征指标实现（DINO 相似度、RAFT 光流等）。这些代理量的问题不是不准，而是<strong>动态范围被压死</strong>：一致性分普遍卡在 97%+，模型之间无法区分。<strong>EvalCrafter</strong> 走了另一条路，直接雇人评，代价是不可扩展、无法做成奖励模型。<strong>FETV</strong> 给 prompt 打细粒度类别标签再算 CLIP-SIM，改善的是覆盖度而非指标本身的可靠性。</p><p><strong>T2VQA</strong> 是最接近的并发工作，也是在人工评分上训模型。论文列了三点差异：VideoFeedback 有多维度评分而非单一 MOS，规模是 T2VQA 的 4 倍，且骨干用的是预训练视频语言基础模型。这三条里前两条是数据层面的，第三条是架构层面的。</p><p>真正的空隙是：<strong>要造一个能当奖励模型用的视频评测器，必须先付大规模人工标注的成本</strong>，而这个成本高到此前没人愿意付。论文的贡献首先是把这笔钱花了（20 名标注员、4 周、33.6K 条视频、每人 1K–2K 条）。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从 2024 年初的已知条件出发：图像域已经有 HPSv2、ImageReward、PickScore，它们的配方是统一的——收人类偏好数据，微调一个 CLIP/BLIP 类骨干。这条配方在图像上被反复验证有效。那么视频域为什么没有？答案不是方法问题而是数据问题。</p><p>于是第一个决定是<strong>去付这笔标注成本</strong>。但视频标注比图像贵得多，所以要把预算花在刀刃上：不做 pairwise 偏好（需要的对数是平方级），改做绝对分；不做单一 MOS（信息量太低，也无法解释），改做五个维度。这五维怎么选？论文说是受 VBench、EvalCrafter、FETV 启发，最后定为 Visual Quality、Temporal Consistency、Dynamic Degree、Text-to-Video Alignment、Factual Consistency——前两个是低层视觉，后两个需要世界知识，这正是特征类指标做不到的部分。</p><p>第二个决定是<strong>视频来源要覆盖全质量谱</strong>。如果只用 SOTA 模型生成，分数会全挤在高分区，回归任务退化。所以选了 11 个能力差异很大的模型（从 Text2Video-Zero、LVDM 这类弱模型到 Pika、Sora clip），并且刻意让质量&quot;ranges from high to low in a balanced way&quot;。</p><p>第三个决定是<strong>骨干要能吃多帧</strong>。Mantis-Idefics2-8B 最多支持 128 帧且支持原生分辨率，比通用 VLM 更合适。这一步后来被消融证实：Mantis 版比 Idefics2 版在回归设定下高 12.1 分。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>已有的自动指标全都是<strong>代理量</strong>——用相邻帧余弦相似度代替「时序一致性」，用 CLIP 分代替「文本对齐」。代理量与人类判断之间的差距，靠再设计一个更聪明的代理量是补不上的。唯一的办法是直接监督：花钱让人在多个维度上给几万条真实的生成视频打分，然后训一个模型去拟合这些分数。指标于是从「手工设计的启发式」变成「一个学出来的回归函数」。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据侧（VideoFeedback）</strong>：</p><ul><li><strong>prompt 来源</strong>：VidProM 的 104 万条真实用户 prompt，先过长度过滤（&lt;5 词或 &gt;100 词剔除）与 NSFW 过滤，随机下采到 44.5K，其中 31.6K 实际用于生成。</li><li><strong>视频生成</strong>：11 个 T2V 模型，共 33.6K 条。其中 Pika、Text2Video-Zero、VideoCrafter2、ModelScope 的视频直接取自 VidProM 预生成，LaVie-base、AnimateDiff、LVDM、Hotshot-XL、ZeroScope、Fast-SVD 自行生成，SoRA-Clip 从网上收集 0.9K 条。</li><li><strong>归一化</strong>：统一到 8 fps（高帧率模型下采样、Text2Video-Zero 这类低帧率模型做帧插值），并裁掉 Pika 的水印，使标注员无法从格式反推模型身份。</li><li><strong>标注</strong>：20 名标注员（多为在读研究生），每人 1K–2K 条，五个维度各打 1（Bad）/2（Average）/3（Good）。标注周期约 4 周，期间做随机抽检并对偏松的标注员做校准。</li><li><strong>增强</strong>：全 3 分的视频由专家复审，特别是 SoRA 与 Fast-SVD 的样本，可升到 4（Perfect）；再从 DiDeMo 与 Panda70M 收 4K 条真实视频，用 SSIM/MSE 过滤掉近似静止的，全部标为 5 维皆 4 分。最终 37.6K 条，留 760 条做测试集（680 标注 + 80 增强）。</li></ul><p><strong>模型侧（VideoScore）</strong>：骨干 Mantis-Idefics2-8B，学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>，8×A100(80G) 训 1 epoch，6 小时。两种打分方式：<strong>generative</strong>，让模型按固定文本格式输出，用正则抽出 5 个整数；<strong>regression</strong>，把 LM head 换成输出 5 个 logit 的线性层，用 MSE 训。</p><p><strong>使用侧</strong>：给一条视频与其 prompt，模型直接吐 5 个分数；做偏好比较时取五维均值，高者为胜。论文还演示了 best-of-K 采样（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>，700 条 EvalCrafter prompt，选五维均分最高的那条）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化很轻，核心只有一个训练目标与两个相关性统计量。</p><p>回归版本把打分写成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">b</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> 是 Mantis 的多模态表示，训练目标是逐维 MSE：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.3171em;vertical-align:-1.516em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">5∣</span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mord">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.809em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">c</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">s</span><span class="mclose mtight">)</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.0278em;">D</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.516em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.404em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord"><span class="delimsizing size1">)</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:1.054em;"><span style="top:-3.3029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span></span></p><p>这里有一个值得点出的建模差异：生成式打分被限制在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mclose">}</span></span></span></span> 四个离散标签上，而回归头输出连续值。论文把回归全面更优归因于「更细粒度」，从相关性统计的角度这是有道理的——<strong>Spearman 相关是基于秩的，而离散化会制造大量并列名次，机械地压低相关系数</strong>。这一条论文没有明说，属于基于证据的推断，但它能同时解释 GenAI-Bench 上 59.0→78.5 这种量级的跳变。</p><p>评价用两个量。Spearman 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 定义为原始分数转秩后的 Pearson 相关；pairwise accuracy 则是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Acc</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.8374em;vertical-align:-1.516em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.809em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.0822em;">P</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.516em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mord mathrm">sign</span></span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop"><span class="mord mathrm">sign</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">]</span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5678em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">ˉ</span></span></span></span></span></span></span></span></span></span> 是五维均值，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> 是人类偏好。注意这个聚合方式是<strong>无权重的等权平均</strong>，它隐含假设五个维度对整体偏好的贡献相同——论文没有对这个假设做任何检验。</p><p>标注质量用 Fleiss&#39; <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 与 Krippendorff&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 度量，两者都是「实际一致度相对随机一致度」的归一化：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">o</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">/</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 表示标注员之间的一致性不高于随机。这个细节在下一节会变得很重要。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：VideoScore 与人类的相关性能到多少？</strong> 在 VideoFeedback-test（760 条）上按 Spearman <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 评。VideoScore (gen) 五维平均 <strong>77.1</strong>，最好的基线 GPT-4o 是 23.0，差 54.1 分。逐维看：Visual Quality 86.2、Temporal 80.3、Dynamic Degree 77.6、Text Alignment 59.4、Factual 82.1。特征类指标几乎全线崩溃——PIQE −10.1、BRISQUE −20.3、CLIP-Score −7.2 都是负相关，SSIM-dyn 在 Dynamic Degree 上有 31.5 但其它四维全负。这一组结论很硬：<strong>图像质量评估指标不能简单迁移到视频</strong>。</p><p><strong>问题二：能不能泛化到留出的评测集？</strong> 这里结论就分裂了。GenAI-Bench 视频偏好上 VideoScore (reg) 拿 <strong>78.5</strong>，超过第二名 Gemini-1.5-Flash 的 67.1（+11.4）。VBench 五个子维度上 4/5 最高，平均 +16.1。但 <strong>EvalCrafter 上是输的</strong>：Visual 42.4 vs EvalCrafter 自带指标的 55.4（−13.1），Temporal 51.3 vs 56.7（−5.4），只有 Text Align 59.5 以 +4.4 领先。同样在 VBench 的 Dynamic Degree 上，SSIM-dyn 拿 84.2 而 VideoScore 只有 68.0（−16.2）。论文摘要只强调 GenAI-Bench 与 VBench 的胜利。</p><p><strong>问题三：回归还是生成式打分？</strong> 回归全面更优，且差距极大：EvalCrafter 平均 27.6→51.1，GenAI-Bench 59.0→78.5，VBench 58.7→73.0。唯一例外是 VideoFeedback-test 自身（77.1 vs 75.7），即<strong>训练分布内生成式略好、分布外回归大幅更好</strong>。</p><p><strong>问题四：骨干选择重要吗？</strong> VideoLLaVA-7B 四基准平均 42.7，Idefics2-8B 47.5，Mantis-Idefics2-8B 55.6（生成式）。回归设定下 Mantis 比 Idefics2 高 12.1。有意思的是专为视频理解设计的 VideoLLaVA 反而最差。</p><p><strong>问题五：能不能当奖励用？</strong> 用 VideoScore 做 best-of-5，在 8 个 T2V 模型上跑 700 条 EvalCrafter prompt，再用 EvalCrafter 自己的指标评。多数模型多数维度上升，最大的是 HotShot-XL（平均 53.69→61.22，T2V Align 46.83→69.52）。但<strong>有反例</strong>：AnimateDiff 的平均分 62.16→61.87 反降，T2V Align 72.79→70.83；LVDM 的 T2V Align 44.61→43.16 也降。论文的措辞是&quot;most scores have increased&quot;，准确但需要注意例外。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：视频自动指标落后的根因是没有大规模人工多维评分数据，而不是没有好的启发式。VideoFeedback 花 20 人 4 周标了 33.6K 条来自 11 个模型的生成视频，五个维度各打 1–4 分，再补 4K 条真实视频作为满分锚点。在此之上把 Mantis-Idefics2-8B 的 LM head 换成回归头训 1 epoch，得到 VideoScore。它在自家测试集上 Spearman 77.1（比 GPT-4o 高 54.1），在 GenAI-Bench 偏好判断上 78.5（比最好的 MLLM 高 11.4）。但在 EvalCrafter 的视觉与时序两维上它输给 EvalCrafter 自带指标 13.1 和 5.4 分，在 VBench 的 Dynamic Degree 上输给最朴素的 SSIM-dyn 16.2 分。</p><p><strong>三句话版</strong>：付钱标 37.6K 条生成视频的五维分数，再训一个 8B 多模态回归器，把「手工代理指标」换成「学出来的打分函数」。分布内相关性碾压所有基线，跨基准偏好判断也明显更好。但在有独立人工标注的 EvalCrafter 上，它并没有超过该基准自己的指标。</p><p><strong>一句话版</strong>：视频指标的瓶颈是标注数据，不是模型设计。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>VideoFeedback 的人工标签本身足够可靠，可以作为「人类判断」的定义</strong>。</p><p>论文自己的表 3 直接动摇了这一点。两轮试标的 Inter-Annotator Agreement 里，Trial 2（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span>）的 Fleiss&#39; <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 与 Krippendorff&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 分别是：Visual Quality <strong>0.088 / 0.078</strong>，Text-to-Video Alignment <strong>0.125 / 0.205</strong>，Factual Consistency <strong>−0.089 / −0.106</strong>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 意味着标注员之间的一致性与随机猜测无异，负值更糟。只有 Temporal Consistency（0.562/0.579）和 Dynamic Degree（0.565/0.620）算得上中等一致。</p><p>论文把结论建立在另一个统计量上——Match Ratio 全都在 0.57–0.91，看起来很高。但 Match Ratio 不扣除随机一致度：在四分类且分布严重偏斜时，两个人独立乱猜也能撞上相当比例。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 存在的全部意义就是扣掉这一项，而扣完之后三个维度归零。正文对此的表述是「<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 在 0.4 或 0.5 左右，足以开始大规模标注」，这个概括只对 Trial 1 成立，Trial 2 的数据与之矛盾。</p><p>如果这个假设不成立，代价是全局性的：VideoScore 在 VideoFeedback-test 上的 77.1 就变成「与一组不自洽的标注拟合得很好」，而不是「与人类判断一致」。这也能自然解释为什么它在有独立人工标注的 EvalCrafter 上表现最弱——那里的真值来自另一套标注流程（1–5 分、每条三人）。一致性最高的两个维度（Temporal、Dynamic）恰好是最能用简单特征算出来的两个，而一致性最低的三个（Visual Quality、Text Alignment、Factual）恰好是最需要 MLLM 的三个。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要重训 8B 模型，也不需要重新标注。</p><ul><li><strong>数据</strong>：VideoFeedback 与 VideoScore 权重都已公开。</li><li><strong>步骤一（诊断标签噪声）</strong>：在 VideoFeedback-test 上，对每个维度分别计算 VideoScore 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>，并与该维度在 Trial 2 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 做散点。假设是二者正相关——即模型在标注员一致的维度上更准。</li><li><strong>步骤二（估计上界）</strong>：用 Spearman-Brown 或简单的分半法，从标注数据估计「人类对人类」的相关上界 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">hh</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。把 77.1 与这个上界比较，而不是与 GPT-4o 的 23.0 比较。</li><li><strong>步骤三（跨标注体系检验）</strong>：直接在 EvalCrafter 的 2541 条视频上，比较 VideoScore 与「一个只用 CLIP-sim + SSIM-sim 线性组合」的极简基线。原文表 6 显示 CLIP-sim 在 Temporal 维已有 53.5，接近 VideoScore 的 51.3。</li><li><strong>判据</strong>：若步骤一的相关显著，则标签噪声是主导误差源，方法本身没问题、数据需要重做；若不相关，则问题在骨干或训练目标。若步骤三中极简基线打平或胜出，说明 8B 模型在跨标注体系上没有带来实质增益。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的反例是给「VideoScore 学到了人类偏好」一个<strong>替代解释</strong>：它可能主要学到了「这条视频出自哪个模型」。</p><p>论证如下。VideoFeedback 的 33.6K 条视频来自 11 个模型，而这些模型的质量差异被论文刻意设计成&quot;from high to low&quot;。同一个模型的输出在分辨率、色调、伪影模式、运动幅度上高度同质——即使做了 8fps 归一化和去水印，模型指纹依然存在。一个足够强的 8B 多模态模型完全可以先识别模型身份，再输出该模型的平均分。这样的模型在 VideoFeedback-test 上会拿到很高的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>（因为模型身份确实与质量强相关），但在换了生成器分布的基准上就会退化——这与 EvalCrafter 上的表现下滑完全一致（EvalCrafter 用的是 Pika、Gen2、Floor33、ModelScope、ZeroScope，其中 Gen2 与 Floor33 不在训练集中）。</p><p>设计判别实验：在 VideoFeedback-test 上训一个<strong>只看视频、不看 prompt、不看标签的模型身份分类器</strong>，测其准确率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span>。若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> 很高（比如 &gt;70%），再做关键一步——按模型身份分层，在<strong>每个模型内部</strong>单独计算 VideoScore 与人类分的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>。若组内 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 大幅低于全局 77.1，则说明大部分相关性来自组间差异（即模型身份），替代解释成立。</p><p>第二条攻击针对 best-of-K 的证据力。论文用 VideoScore 选出 best-of-5，再用 EvalCrafter 指标评估。但两者共享一个混杂因子：<strong>被选出的视频系统性地更清晰、运动更少</strong>（DD 是五维之一但等权，而 Visual Quality 与 Temporal Consistency 各占一份）。缺的对照是「用一个只看清晰度的朴素指标做 best-of-5」。如果朴素指标能拿到相近的提升，那 best-of-K 实验就不构成对 VideoScore 特有价值的证据。AnimateDiff 与 LVDM 上 T2V Align 反降，恰好是这个混杂在起作用的迹象。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：VideoFeedback 把「评估」定义成对<strong>孤立视频</strong>的绝对打分，因此不得不承受绝对分标注固有的高噪声（表 3 里三个维度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>）。而心理测量学早有结论：人对绝对量级的判断不稳定，对<strong>相对比较</strong>的判断稳定得多。论文选绝对分是为了控制标注量（pairwise 的对数是平方级），这是一个理性的工程折中，但它把噪声焊死在了数据里。</p><p><strong>新 framing</strong>：不要求人给分，只要求人排序，然后用<strong>排序学习</strong>把稀疏的比较恢复成连续的多维分数。关键是不必标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">n</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 对——主动学习与自适应比较可以把复杂度压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">n</span><span class="mclose">)</span></span></span></span> 量级。这不是「换个损失函数」，而是换一个测量对象：从「这条视频有多好」变成「这条视频在群体中的位置」。</p><p><strong>可借鉴的相邻领域工具</strong>：一是 Bradley-Terry 与 Thurstone 模型（把成对比较恢复成潜在效用尺度），LLM 侧的 Chatbot Arena 已经把这套用得很成熟；二是**计算机自适应测验（CAT）**里的 item selection，它专门解决「用最少的比较把被试的能力值估到给定精度」这个问题，正好对应「用最少的标注把视频的五维潜在分估准」。</p><p><strong>第一个实验</strong>：在 VideoFeedback 的一个子集上做同预算对照。固定标注员总工时，一路继续标绝对分，另一路改标成对比较（用 Thurstone 模型恢复连续分）。两路各自训一个同架构的 VideoScore，在 <strong>EvalCrafter 与 GenAI-Bench</strong> 这两个外部集上比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 与 pairwise accuracy。同时报告两路各自的标注一致性（绝对分用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span>，比较用 pairwise agreement）。假设是：比较标注的一致性会在 Visual Quality 与 Factual Consistency 这两个当前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 的维度上显著更高，而外部集的相关性提升也集中在这两维——这将直接把「指标不准」的责任从模型转到测量方式上。</p>',61)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
